-- Sample app schema for Microsoft SQL Server 2022 (SAMPLE_DB=mssql). SQL Server has no CREATE TABLE
-- IF NOT EXISTS: each statement checks OBJECT_ID or sys.indexes first. TIMESTAMP is rowversion on
-- SQL Server, so time columns are DATETIME2. Statements end with ';' at the end of a line
-- (ShopSchema splits on it). Data is generated by ShopSchema when the tables are empty.
IF OBJECT_ID(N'customers', N'U') IS NULL CREATE TABLE customers (
  id BIGINT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(200) NOT NULL
);
IF OBJECT_ID(N'products', N'U') IS NULL CREATE TABLE products (
  id BIGINT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  price DECIMAL(12, 2) NOT NULL
);
IF OBJECT_ID(N'orders', N'U') IS NULL CREATE TABLE orders (
  id BIGINT PRIMARY KEY,
  customer_id BIGINT NOT NULL,
  status VARCHAR(20) NOT NULL,
  amount DECIMAL(12, 2) NOT NULL,
  created_at DATETIME2 NOT NULL
);
IF OBJECT_ID(N'order_items', N'U') IS NULL CREATE TABLE order_items (
  id BIGINT PRIMARY KEY,
  order_id BIGINT NOT NULL,
  product_id BIGINT NOT NULL,
  quantity INT NOT NULL
);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'order_items_order_idx') CREATE INDEX order_items_order_idx ON order_items (order_id);
IF OBJECT_ID(N'audit_log', N'U') IS NULL CREATE TABLE audit_log (
  id BIGINT IDENTITY(1, 1) PRIMARY KEY,
  message VARCHAR(500) NOT NULL,
  created_at DATETIME2 NOT NULL
);
